import{_ as n,l as i,o as e,c as l,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"交易层级归因","description":"","frontmatter":{"title":"交易层级归因","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/trade-level-attribution.md","filePath":"quant/trade-level-attribution.md","lastUpdated":1789023840000}'),u={name:"quant/trade-level-attribution.md"};function B(c,a,E,m,_,A){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="交易层级归因" tabindex="-1">交易层级归因 <a class="header-anchor" href="#交易层级归因" aria-label="Permalink to &quot;交易层级归因&quot;">​</a></h1><div class="epigraph"><p>基金级超额是许多笔成交、许多个持有日的和；不拆到交易与实施缺口，配置、选择与冲击会继续混在同一个 alpha 里。</p><footer>—— 持仓会计见 Brinson, Hood and Beebower；实施缺口见 Perold, The Implementation Shortfall, 1988</footer></div><p><a href="/quant/twr-vs-mwr">上一课</a>把过程收益与口袋收益分开。交易层级的缺口是<strong>再往下拆</strong>：决策价 → 下单 → 成交 → 持有 → 卖出。主干 <a href="/quant/brinson">Brinson 归因</a>、<a href="/quant/factor-attribution">因子归因</a>、<a href="/quant/slippage-attribution">滑点归因</a> 已写三套账。本课给业绩单元的接口：何时用哪一套，以及为什么「IR 很好」仍可能是没算冲击。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Brinson 回答配置 vs 选择（格子会计）。因子归因回答风格 vs 残差（风险模型）。两者都用持仓或收益，不自动含「若用决策价成交会怎样」。Perold 的实施缺口把纸面组合与真实组合的差写成冲击与时机。问题是对齐：决策时点必须预注册，否则滑点变成事后选价。多空与 RV 的融资、借券应进交易成本腿，不要留在「选择 alpha」。</p><p>与被动流、回购流：机械成交的冲击应标成流的成本或收益，而不是选股。与短波动：Theta 与缺口要按合约记账，不能进股票 Brinson 格子。</p><h3 id="交易加总必须还原-twr" tabindex="-1">交易加总必须还原 TWR <a class="header-anchor" href="#交易加总必须还原-twr" aria-label="Permalink to &quot;交易加总必须还原 TWR&quot;">​</a></h3><p>子账之和不等于报告净值，归因就只是故事。公司行动、期货展期、费用计提、估值定价源都要有格子。日终中价回测与成交回报之间的差，应进滑点，而不是进信号 IC。</p><p><span class="marginnote">Litterman 热点指出主动方差来自哪些名字；交易归因指出这些名字上的 P&amp;L 来自持有还是来自冲击。两者一起才能决定是减限额还是改执行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层并行：Brinson（或因子）月频持仓；实施缺口按订单；融资/借券/费用单独。交易级：每笔的决策价、基准价（到达价、VWAP、拍卖）、成交、标记。汇总：按策略桶（地图上的多空、RV、ARP…）出净 IR，避免一只基金一个数。抽查：大额日、调仓日、公告日是否异常。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>纸面 alpha 在下单时变成对流动性的需求。做市商与拍卖规则决定缺口。归因把「想法」与「成交」切开，才能反馈到信号衰减还是执行衰减——生命周期课的退役否则会裁错对象。</p>',13)),(e(),s(h,null,{default:r(()=>[p(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Dec%5B%22%E5%86%B3%E7%AD%96%E4%BB%B7%22%5D%20--%3E%20Ord%5B%22%E8%AE%A2%E5%8D%95%22%5D%0A%20%20Ord%20--%3E%20Fill%5B%22%E6%88%90%E4%BA%A4%22%5D%0A%20%20Fill%20--%3E%20Hold%5B%22%E6%8C%81%E6%9C%89%20P%20and%20L%22%5D%0A%20%20Dec%20--%3E%20Gap%5B%22%E5%AE%9E%E6%96%BD%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20Fill%20--%3E%20Gap%0A%20%20Hold%20--%3E%20Brin%5B%22Brinson%20%E6%88%96%E5%9B%A0%E5%AD%90%E8%B4%A6%22%5D%0A%20%20Gap%20--%3E%20Slip%5B%22%E6%BB%91%E7%82%B9%E8%B4%A6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何把亏损归到「异常波动」以回避审计。场外协商成交的基准价必须事先定义。下一课：即便账算清了，夏普和 IR 仍有抽样误差。下一课程将从撮合引擎解释成交从何而来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交易归因把决策、冲击与持有切开，且必须还原 TWR。</li><li>Brinson / 因子 / 滑点三套账对象不同，不要互相替代。</li><li>流与融资要进成本腿，不要留在选择 alpha。</li><li>出处：Brinson, Hood and Beebower, <em>FAJ</em>, 1986；Perold, 1988；滑点见本栏滑点归因课。</li></ul>',4))])}const q=n(u,[["render",B]]);export{b as __pageData,q as default};
